edit('src/scrollbar.rs', [
("""    /// With nothing to scroll, the thumb fills the track; otherwise it is as
    /// tall as the share of the list in view, and never too short to grab.""", """    /// The bevel is a pixel wide, lit along the thumb's top and left, shaded
    /// along its bottom and right, within the thumb, with no edge over
    /// another; and faint on dark and light surfaces alike.
    #[test]
    fn thumb_has_a_faint_pixel_bevel() {
        let thumb = Bounds::new(point(px(10.), px(100.)), size(px(17.), px(60.)));
        for dark in [true, false] {
            let colors = super::scroll_colors(dark);
            let edges = super::thumb_bevel(thumb, &colors);
            assert_eq!(edges.len(), 4);
            let area: f32 = edges
                .iter()
                .map(|(edge, _)| (edge.size.width * edge.size.height.as_f32()).as_f32())
                .sum();
            // Its outline, a pixel wide, counted once.
            assert_eq!(area, 2. * 17. + 2. * 58.);
            for (edge, color) in &edges {
                assert!(
                    edge.left() >= thumb.left()
                        && edge.right() <= thumb.right()
                        && edge.top() >= thumb.top()
                        && edge.bottom() <= thumb.bottom()
                );
                assert!(edge.size.width == px(1.) || edge.size.height == px(1.));
                let lit = *color == colors.light;
                if lit {
                    assert!(edge.top() == thumb.top() || edge.left() == thumb.left());
                } else {
                    assert!(edge.bottom() == thumb.bottom() || edge.right() == thumb.right());
                }
            }
            for l in if dark { [0.18, 0.27] } else { [0.82, 0.91] } {
                let surface = gpui_kit::hsla(0., 0., l, 1.);
                let lit = surface.blend(colors.light).l - l;
                let shaded = l - surface.blend(colors.shade).l;
                assert!(lit > 0. && lit < 0.1, "{dark} light {lit}");
                assert!(shaded > 0. && shaded < 0.1, "{dark} shade {shaded}");
            }
        }
        assert!(super::thumb_bevel(Bounds::new(point(px(0.), px(0.)), size(px(1.), px(1.))), &super::scroll_colors(true)).is_empty());
    }

    /// With nothing to scroll, the thumb fills the track; otherwise it is as
    /// tall as the share of the list in view, and never too short to grab."""),
])

